$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "5.0.1"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version recent ScoresR scanner..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\scoresr_recent_preview_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\scoresr_recent_preview_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 5.0.1 installed."
Write-Host "Scans recent completed/current ScoresR programs across exposed clubs."
Write-Host ""
Write-Host "Run:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.scoresr_recent_preview_cli --since 2026-07-01'
